import base64
import logging
import re
from enum import Enum
from pathlib import Path

import click.testing
import pytest
import yaml

import frontends.cli as cli
from trudag.dotstop.core.constants import FILE_MARKER
from trudag.error import ExitCodes
from trudag.utils import DOTSTOP_DEFAULT_FILENAME, NEEDS_DEFAULT_FILENAME, make_dotfile


class FrontmatterToAdd(Enum):
    reference = 0
    scores = 1
    validators = 2


def add_to_needs_file(
    example_workspace,
    project_path,
    item_names,
    part_to_add: FrontmatterToAdd | None = None,
):
    def _replace_content(item, new_content):
        item_content = item.read_text()
        item.write_text(item_content.replace("normative: true", new_content))

    needs_file = project_path / NEEDS_DEFAULT_FILENAME
    items_in_resolved = []
    existing_items = []
    for item_name in item_names:
        match part_to_add:
            case FrontmatterToAdd.validators:
                item = Path(f"./{item_name}.md")
                _replace_content(
                    item,
                    "normative: true\nevidence:\n    type: test_type\n    configuration:\n        test_key: test_value",
                )
            case FrontmatterToAdd.reference:
                item = Path(f"./{item_name}.md")
                _replace_content(
                    item,
                    f'normative: true\nreferences:\n    - type: "file"\n      path: ./{item}',
                )

    if existing_items_found := re.findall(
        r'.*".*".*\[sha=.*\];', example_workspace["needs_dot"]
    ):
        existing_items.append(existing_items_found)

    items_in_resolved = "\n".join(f'"{item_name}";' for item_name in item_names)
    needs_file.write_text(f"""{FILE_MARKER}
digraph G {{
    {items_in_resolved}
}}
""")


def imported_files_checks(import_dir: Path, files: list[str]) -> list[bool]:
    checks = []
    checks.append(import_dir.exists())
    for f in files:
        checks.append((import_dir / Path(f)).is_file())
    return checks


@pytest.mark.parametrize(
    "test_workspace",
    ["empty_workspace"],
    indirect=True,
)
def test_export_without_needs(workspace_repo, caplog):
    Path(".needs.dot").unlink()
    runner = click.testing.CliRunner()

    assert (
        runner.invoke(
            cli.main, ["export", "--artifact", "data.json", "-P", "test"]
        ).exit_code
        == ExitCodes.SUCCESS
    )

    expected_log = (
        "trudag.dotstop.core.artifact",
        logging.WARNING,
        "needs dotstop file does not exist, artifact will have no needs.",
    )

    assert expected_log in caplog.record_tuples


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_export_with_referenced_needs_pass(
    workspace_repo, test_workspace, example_reference
):
    namespace = "testing"
    needs_dir = Path("needs")
    needs_items = [needs_item.name for needs_item in test_workspace["needs_items"]]
    runner = click.testing.CliRunner()

    assert (
        runner.invoke(
            cli.main,
            ["export", "--artifact", "data.json", "-P", "test"],
        ).exit_code
        == ExitCodes.SUCCESS
    )
    result = runner.invoke(
        cli.main,
        [
            "import",
            "--artifact",
            "data.json",
            "-d",
            needs_dir.name,
            "-n",
            namespace,
        ],
    )
    assert result.exit_code == ExitCodes.SUCCESS
    assert any(
        imported_files_checks(
            needs_dir,
            [f"{namespace}.{item}.md" for item in needs_items],
        )
    )

    # Make sure the referenced needs items from the artifact are imported correctly.
    for need_item in needs_items:
        parts = Path(f"needs/{namespace}.{need_item}.md").read_text().split("---\n\n")
        assert parts
        needs_frontmatter = yaml.safe_load(parts[0])
        assert needs_frontmatter
        for needs_reference in needs_frontmatter["resolved_references"]:
            assert needs_reference["type"] == "file"
            assert (
                needs_reference["origin"] == f"{namespace}://{str(example_reference)}"
            )
            assert (
                base64.b64decode(needs_reference["text_content"]).decode()
                == """````md
Alice: 0800 00 1066
````
"""
            )
    # Assert that the reference is rendered correctly in report.
    result = runner.invoke(cli.main, ["publish", "--no-validate"])
    assert result.exit_code == ExitCodes.SUCCESS
    with Path("docs/trustable/testing.AOU.md").open("r") as fp:
        file_content = fp.read()
        assert "Alice: 0800 00 1066" in file_content


@pytest.mark.parametrize(
    "test_workspace",
    ["empty_workspace"],
    indirect=True,
)
def test_export_with_empty_needs_and_empty_dotfile(workspace_repo, caplog):
    # We overwrite dotstop files with empty graphs.
    dotstop_files = [Path(".needs.dot"), Path(".dotstop.dot")]
    for dotstop_file in dotstop_files:
        dotstop_file.unlink()
        make_dotfile(dotstop_file, "G")
    runner = click.testing.CliRunner()

    assert (
        runner.invoke(
            cli.main, ["export", "--artifact", "data.json", "-P", "test"]
        ).exit_code
        == ExitCodes.SUCCESS
    )

    expected_logs = [
        (
            "trudag.dotstop.core.artifact",
            logging.WARNING,
            "dotstop file does not contain any items, artifact will have no resolved items or scores.",
        ),
        (
            "trudag.dotstop.core.artifact",
            logging.WARNING,
            "needs dotstop file does not contain any items, artifact will have no needs.",
        ),
    ]

    for expected_log in expected_logs:
        assert expected_log in caplog.record_tuples


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_export_with_validator_needs_fail(workspace_repo, test_workspace, caplog):
    needs_items = [
        "ASN-2",  # This is an item with no score/validator/evidences initially.
    ]
    runner = click.testing.CliRunner()

    # We add a test validator to the needs items.
    add_to_needs_file(
        test_workspace,
        workspace_repo.working_dir,
        needs_items,
        FrontmatterToAdd.validators,
    )

    result = runner.invoke(
        cli.main, ["export", "--artifact", "data.json", "-P", "test"]
    )
    assert result.exit_code != ExitCodes.SUCCESS
    assert (
        "frontends.cli.utils",
        logging.CRITICAL,
        "Needs item ASN-2 should not have evidence or associated score.",
    ) in caplog.record_tuples


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_artifact_export_import_pass(workspace_repo, test_workspace):
    namespace = "testing"
    import_dir = Path("needs")
    needs_items = [needs_item.name for needs_item in test_workspace["needs_items"]]
    runner = click.testing.CliRunner()

    result = runner.invoke(
        cli.main, ["export", "--artifact", "data.json", "-P", "test"]
    )

    assert result.exit_code == ExitCodes.SUCCESS

    result = runner.invoke(
        cli.main,
        [
            "import",
            "--artifact",
            "data.json",
            "-d",
            import_dir.name,
            "-n",
            namespace,
        ],
    )
    assert result.exit_code == ExitCodes.SUCCESS
    assert all(
        imported_files_checks(
            import_dir, [f"{namespace}.{item}.md" for item in needs_items]
        )
    )

    assert runner.invoke(cli.main, ["publish", "-a"]).exit_code == ExitCodes.SUCCESS


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_import_atomicity_on_fail(workspace_repo, test_workspace):
    namespace = "testing"
    import_dir = Path("needs")
    needs_items = ["ASN-2", "EXP-1"]

    runner = click.testing.CliRunner()

    add_to_needs_file(test_workspace, workspace_repo.working_dir, needs_items)

    original_dot_source = DOTSTOP_DEFAULT_FILENAME.read_text()
    result = runner.invoke(
        cli.main, ["export", "--artifact", "data.json", "-P", "test"]
    )

    assert result.exit_code == ExitCodes.SUCCESS

    result = runner.invoke(
        cli.main,
        [
            "import",
            "--artifact",
            "data.json",
            "-d",
            import_dir.name,
            "-n",
            namespace,
            "-R",
        ],
    )
    assert result.exit_code != ExitCodes.SUCCESS
    # we should expect none of the needs files to have been created since we failed on import and also the dot file to be the same as before.
    assert not all(
        imported_files_checks(
            import_dir,
            [f"{namespace}.{item}.md" for item in needs_items],
        )
    )
    assert DOTSTOP_DEFAULT_FILENAME.read_text() == original_dot_source

    # we should still be able to run publish
    assert runner.invoke(cli.main, ["publish", "-a"])


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_artifact_import_with_duplicate_namespaces(
    workspace_repo, test_workspace, caplog
):
    namespace = "testing"
    import_dir = Path("needs")
    needs_items = ["ASN-2"]

    runner = click.testing.CliRunner()

    expected_log = (
        "frontends.cli.utils",
        logging.CRITICAL,
        f"namespace: {namespace} is already present in the local dotstop file, namespaces must be unique.",
    )

    add_to_needs_file(test_workspace, workspace_repo.working_dir, needs_items)

    assert (
        runner.invoke(
            cli.main, ["export", "--artifact", "data.json", "-P", "test"]
        ).exit_code
        == ExitCodes.SUCCESS
    )

    assert (
        runner.invoke(
            cli.main,
            [
                "import",
                "--artifact",
                "data.json",
                "-d",
                import_dir.name,
                "-n",
                namespace,
            ],
        ).exit_code
        == ExitCodes.SUCCESS
    )
    # We expect no duplicate log warning just yet
    assert expected_log not in caplog.record_tuples

    assert all(
        imported_files_checks(
            import_dir,
            [f"{namespace}.{item}.md" for item in needs_items],
        )
    )
    assert runner.invoke(cli.main, ["publish", "-a"])

    # Now we try to import the artifact again with the same namespace as before, this should fail.
    result = runner.invoke(
        cli.main,
        ["import", "--artifact", "data.json", "-d", import_dir.name, "-n", namespace],
    )
    assert result.exit_code != ExitCodes.SUCCESS
    assert expected_log in caplog.record_tuples
